(function () {
  "use strict";

  var CONFIG = {
    startDate: "2026-10-01T00:00:00+07:00",
    endDate: "2026-11-02T23:59:59+07:00",
    storagePrefix: "chiroot_after_dark_v1"
  };

  var ASSETS = {
    bat: "data:image/png;base64,",
    bats_banner: "data:image/png;base64,",
    candy: "data:image/png;base64,",
    ghost: "data:image/png;base64,",
    magic_dust_banner: "data:image/png;base64,",
    moon: "data:image/png;base64,",
    pumpkin: "data:image/png;base64,",
    sparkle: "data:image/png;base64,",
    spider_corner: "data:image/png;base64,",
    spooky_cat: "data:image/png;base64,",
    web: "data:image/png;base64,"
  };

  var messages = [
    "A tiny treat for your next late-night listening session. 🍬",
    "May your evening be cozy and your playlist full of good finds. 🌙",
    "A friendly little ghost says: take a breath, then press play. 👻",
    "You found a pocket of Halloween cheer. Keep the good music close. ✨",
    "Pumpkin-approved advice: make yourself comfy and enjoy the quiet. 🎃"
  ];

  function injectStyles() {
    var style = document.createElement("style");
    style.textContent = `
      .chiroot-haunt-decor{position:fixed;inset:0;z-index:2;overflow:hidden;pointer-events:none;isolation:isolate}
      .chiroot-haunt-decor img{position:absolute;display:block;height:auto;object-fit:contain;pointer-events:none;user-select:none;opacity:.17;filter:saturate(.88);animation:chirootHauntFloat 10s ease-in-out infinite}
      .chiroot-haunt-decor .haunt-bats{width:min(100vw,1600px);top:0;left:50%;transform:translateX(-50%);opacity:.12;animation:none}
      .chiroot-haunt-decor .haunt-dust{width:min(100vw,1600px);bottom:0;left:50%;transform:translateX(-50%);opacity:.13;animation:none}
      .chiroot-haunt-decor .haunt-web{width:clamp(90px,16vw,210px);left:-24px;top:12%;opacity:.12;animation-delay:-3s}
      .chiroot-haunt-decor .haunt-moon{width:clamp(64px,9vw,118px);right:5%;top:17%;opacity:.2;animation-delay:-5s}
      .chiroot-haunt-decor .haunt-ghost{width:clamp(58px,8vw,108px);left:4%;top:52%;opacity:.2;animation-delay:-2s}
      .chiroot-haunt-decor .haunt-candy{width:clamp(65px,9vw,112px);right:4%;top:48%;opacity:.17;animation-delay:-7s}
      .chiroot-haunt-decor .haunt-pumpkin{width:clamp(72px,10vw,132px);left:8%;bottom:7%;opacity:.17;animation-delay:-4s}
      .chiroot-haunt-decor .haunt-cat{width:clamp(64px,9vw,118px);right:10%;bottom:7%;opacity:.18;animation-delay:-6s}
      .chiroot-haunt-decor .haunt-sparkle{width:clamp(42px,6vw,80px);left:21%;top:30%;opacity:.17;animation-delay:-1s}
      .chiroot-haunt-decor .haunt-bat{width:clamp(45px,6vw,78px);right:22%;top:32%;opacity:.16;animation-delay:-8s}
      .chiroot-haunt-decor .haunt-spider{width:clamp(70px,9vw,120px);right:0;top:0;opacity:.13;animation-delay:-4s}
      @keyframes chirootHauntFloat{0%,100%{translate:0 0;rotate:-3deg}50%{translate:0 -11px;rotate:3deg}}
      .chiroot-haunt-ui{position:relative;z-index:6;margin:0 0 12px;font-family:'Patrick Hand','Kalam',system-ui,sans-serif;color:#171522}
      .chiroot-haunt-badge{display:inline-flex;align-items:center;gap:8px;min-height:34px;padding:5px 12px;border:2px solid #5c466b;border-radius:999px;background:#171522;color:#fff1d6;font:600 15px/1.1 'Kalam','Patrick Hand',sans-serif;cursor:pointer;box-shadow:2px 3px 0 rgba(92,70,107,.22)}
      .chiroot-haunt-badge:hover{transform:translateY(-1px);background:#282033}
      .chiroot-haunt-badge:focus-visible,.chiroot-haunt-ui button:focus-visible{outline:3px solid #ff8a3d;outline-offset:3px}
      .chiroot-haunt-badge-mark{display:grid;place-items:center;width:20px;height:20px;border-radius:50%;background:#ff8a3d;color:#171522;font-size:13px}
      .chiroot-haunt-card{position:relative;margin-top:9px;padding:14px 46px 14px 16px;background:linear-gradient(135deg,#fff1d6 0%,#f9e7c5 100%);border:2px solid #5c466b;border-radius:16px 13px 17px 14px;box-shadow:0 5px 14px rgba(23,21,34,.1);overflow:hidden}
      .chiroot-haunt-card:after{content:"";position:absolute;right:-20px;bottom:-36px;width:112px;height:112px;background:url("data:image/png;base64,") center/contain no-repeat;opacity:.12;pointer-events:none}
      .chiroot-haunt-card h2{margin:0 0 3px;font:700 27px/1.12 'Caveat','Patrick Hand',cursive;color:#171522}
      .chiroot-haunt-card p{margin:0;font-size:16px;line-height:1.35}
      .chiroot-haunt-close{position:absolute;right:9px;top:9px;width:32px;height:32px;border:1.5px solid #5c466b;border-radius:10px;background:#fff8ea;color:#171522;font-size:18px;cursor:pointer}
      .chiroot-haunt-tools{display:flex;flex-wrap:wrap;align-items:center;gap:8px;margin-top:11px}
      .chiroot-haunt-treat,.chiroot-haunt-motion,.chiroot-haunt-play{min-height:36px;padding:6px 11px;border:1.5px solid #5c466b;border-radius:12px;background:#fffaf0;color:#171522;font:600 14px/1.15 'Patrick Hand','Kalam',sans-serif;cursor:pointer}
      .chiroot-haunt-treat{background:#ff8a3d}
      .chiroot-haunt-play{background:#a78bfa}
      .chiroot-haunt-feedback{flex:1 1 100%;min-height:20px;color:#43354e;font-size:14px}
      .chiroot-haunt-playlist{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:7px;margin-top:11px}
      .chiroot-haunt-vibe{padding:8px 9px;border:1px dashed rgba(92,70,107,.58);border-radius:12px;background:rgba(255,255,255,.45);font-size:14px;line-height:1.2}
      .chiroot-haunt-vibe strong{display:block;font-size:15px;color:#5c466b}
      .chiroot-haunt-caption{margin-top:6px!important;font-size:12px!important;color:#66586b}
      .chiroot-haunt-card[hidden],.chiroot-haunt-ui[hidden]{display:none!important}
      @media(max-width:600px){
        .chiroot-haunt-decor .haunt-web{width:78px;left:-30px;top:10%}
        .chiroot-haunt-decor .haunt-moon{right:1%;top:19%;width:58px}
        .chiroot-haunt-decor .haunt-ghost{left:0;top:61%;width:54px}
        .chiroot-haunt-decor .haunt-candy{right:0;top:56%;width:56px}
        .chiroot-haunt-decor .haunt-pumpkin{left:1%;bottom:4%;width:60px}
        .chiroot-haunt-decor .haunt-cat{right:2%;bottom:4%;width:58px}
        .chiroot-haunt-decor .haunt-sparkle,.chiroot-haunt-decor .haunt-bat,.chiroot-haunt-decor .haunt-spider{display:none}
        .chiroot-haunt-decor .haunt-bats,.chiroot-haunt-decor .haunt-dust{opacity:.08}
        .chiroot-haunt-playlist{grid-template-columns:1fr}
        .chiroot-haunt-card{padding-left:12px}
        .chiroot-haunt-card h2{font-size:25px}
      }
      @media(prefers-reduced-motion:reduce){.chiroot-haunt-decor img{animation:none!important;scroll-behavior:auto}}
      .chiroot-haunt-reduced-motion *, .chiroot-haunt-reduced-motion *::before, .chiroot-haunt-reduced-motion *::after{scroll-behavior:auto!important;animation-duration:.01ms!important;animation-iteration-count:1!important;transition-duration:.01ms!important}
      .chiroot-haunt-reduced-motion .chiroot-haunt-decor img{animation:none!important}
    `;
    document.head.appendChild(style);
  }

  function isEventActive(now) {
    return now >= new Date(CONFIG.startDate) && now <= new Date(CONFIG.endDate);
  }

  function makeImage(className, source) {
    var image = document.createElement("img");
    image.className = className;
    image.src = source;
    image.alt = "";
    image.setAttribute("aria-hidden", "true");
    image.setAttribute("draggable", "false");
    image.addEventListener("error", function () { image.remove(); }, { once: true });
    return image;
  }

  function decorate() {
    var decor = document.createElement("div");
    decor.className = "chiroot-haunt-decor";
    decor.setAttribute("aria-hidden", "true");
    decor.setAttribute("inert", "");
    [
      ["haunt-bats", ASSETS.bats_banner],
      ["haunt-dust", ASSETS.magic_dust_banner],
      ["haunt-web", ASSETS.web],
      ["haunt-moon", ASSETS.moon],
      ["haunt-ghost", ASSETS.ghost],
      ["haunt-candy", ASSETS.candy],
      ["haunt-pumpkin", ASSETS.pumpkin],
      ["haunt-cat", ASSETS.spooky_cat],
      ["haunt-sparkle", ASSETS.sparkle],
      ["haunt-bat", ASSETS.bat],
      ["haunt-spider", ASSETS.spider_corner]
    ].forEach(function (item) {
      decor.appendChild(makeImage(item[0], item[1]));
    });
    document.body.appendChild(decor);
  }

  function addEventUI() {
    var paper = document.querySelector(".paper-card");
    var topbar = document.getElementById("chiroot-topbar");
    if (!paper || !topbar || document.getElementById("chiroot-after-dark")) return;

    var wrapper = document.createElement("section");
    wrapper.className = "chiroot-haunt-ui";
    wrapper.id = "chiroot-after-dark";
    wrapper.setAttribute("aria-label", "Chiroot After Dark Halloween event");

    var badge = document.createElement("button");
    badge.type = "button";
    badge.className = "chiroot-haunt-badge";
    badge.setAttribute("aria-expanded", "true");
    badge.setAttribute("aria-controls", "chiroot-haunt-card");
    badge.innerHTML = '<span class="chiroot-haunt-badge-mark" aria-hidden="true">✦</span><span>After Dark · limited-time Halloween event</span>';

    var card = document.createElement("div");
    card.className = "chiroot-haunt-card";
    card.id = "chiroot-haunt-card";
    card.setAttribute("aria-labelledby", "chiroot-haunt-title");
    card.innerHTML = '<button class="chiroot-haunt-close" type="button" aria-label="Dismiss Chiroot After Dark event card">×</button><h2 id="chiroot-haunt-title">Chiroot After Dark</h2><p>A cozy little corner for late-night listening. Settle in, pick a mood, and let your own records keep you company.</p><div class="chiroot-haunt-playlist" aria-label="Halloween listening moods"><div class="chiroot-haunt-vibe"><strong>🌧 Rainy Window</strong>soft, slow, and snug</div><div class="chiroot-haunt-vibe"><strong>🕯 Midnight Study</strong>quiet focus after dark</div><div class="chiroot-haunt-vibe"><strong>🌙 Moonlit Interlude</strong>a gentle pause between songs</div></div><p class="chiroot-haunt-caption">Use your own music in The Crate. No tracks are added or played automatically.</p><div class="chiroot-haunt-tools"><button type="button" class="chiroot-haunt-play">Play current record</button><button type="button" class="chiroot-haunt-treat">Get a little treat ✦</button><button type="button" class="chiroot-haunt-motion" role="switch" aria-checked="false">Reduced motion: off</button><span class="chiroot-haunt-feedback" role="status" aria-live="polite"></span></div>';

    wrapper.appendChild(badge);
    wrapper.appendChild(card);
    paper.insertBefore(wrapper, topbar);

    var closedKey = CONFIG.storagePrefix + "_dismissed";
    var motionKey = CONFIG.storagePrefix + "_reduced_motion";
    var reducedMotion = false;
    try {
      reducedMotion = localStorage.getItem(motionKey) === "true";
      if (localStorage.getItem(closedKey) === "true") {
        card.hidden = true;
        badge.setAttribute("aria-expanded", "false");
      }
    } catch (error) {
      reducedMotion = false;
    }
    if (reducedMotion) document.documentElement.classList.add("chiroot-haunt-reduced-motion");

    badge.addEventListener("click", function () {
      card.hidden = !card.hidden;
      badge.setAttribute("aria-expanded", String(!card.hidden));
      if (!card.hidden) {
        try { localStorage.removeItem(closedKey); } catch (error) {}
        card.querySelector(".chiroot-haunt-close").focus();
      }
    });

    card.querySelector(".chiroot-haunt-close").addEventListener("click", function () {
      card.hidden = true;
      badge.setAttribute("aria-expanded", "false");
      try { localStorage.setItem(closedKey, "true"); } catch (error) {}
      badge.focus();
    });

    card.querySelector(".chiroot-haunt-treat").addEventListener("click", function () {
      var feedback = card.querySelector(".chiroot-haunt-feedback");
      var message = messages[Math.floor(Math.random() * messages.length)];
      feedback.textContent = message;
    });

    var motionButton = card.querySelector(".chiroot-haunt-motion");
    function updateMotionButton() {
      var enabled = document.documentElement.classList.contains("chiroot-haunt-reduced-motion");
      motionButton.setAttribute("aria-checked", String(enabled));
      motionButton.textContent = "Reduced motion: " + (enabled ? "on" : "off");
    }
    updateMotionButton();
    motionButton.addEventListener("click", function () {
      var enabled = !document.documentElement.classList.contains("chiroot-haunt-reduced-motion");
      document.documentElement.classList.toggle("chiroot-haunt-reduced-motion", enabled);
      try { localStorage.setItem(motionKey, String(enabled)); } catch (error) {}
      updateMotionButton();
    });

    card.querySelector(".chiroot-haunt-play").addEventListener("click", function () {
      var audio = document.getElementById("audio");
      var playButton = document.getElementById("btn-play");
      var addButton = document.getElementById("btn-add-open");
      if (audio && audio.src && audio.readyState > 0 && playButton) {
        playButton.click();
        card.querySelector(".chiroot-haunt-feedback").textContent = "Your current record is ready.";
      } else {
        card.querySelector(".chiroot-haunt-feedback").textContent = "Add one of your own records to The Crate, then press play here.";
        if (addButton) addButton.click();
      }
    });
  }

  function init() {
    if (!isEventActive(new Date())) return;
    injectStyles();
    decorate();
    addEventUI();
  }

  if (document.readyState === "loading") document.addEventListener("DOMContentLoaded", init, { once: true });
  else init();
})();
